import { Suspense, lazy, useEffect, useRef, useState } from "react";
import root from "react-shadow";
import { ChatButton } from "./ChatButton";
import { HubIconButton } from "./HubIconButton";
import { ChatMessage, ChatRequest, ChatResponse, WidgetControls } from "./types";
import { loadRecaptcha } from "../recaptcha";
import styles from "./styles.css?inline";

// Lazy-load the chat panel (and with it the heavy markdown + syntax-highlighter
// dependencies it renders) so they aren't initialized until the user first
// opens the chat. The import() fires on the same click that opens the panel,
// keeping that cost off the initial load of every page that embeds the widget.
const ChatModal = lazy(() =>
  import("./ChatModal").then((m) => ({ default: m.ChatModal }))
);

interface Props {
  recaptchaSiteKey: string;
  ragpiGatewayUrl: string;
  ragpiSources: string[];
  primaryColor?: string;
  secondaryColor?: string;
  logoUrl?: string;
  closedIconPosition?: "bottom-left" | "bottom-right";
  enabled?: boolean;
  // Called once on mount with the imperative controls (and with null on unmount)
  // so the bootstrap in index.tsx can expose them as window.ragpiWidget.
  registerControls?: (controls: WidgetControls | null) => void;
}

export const ChatWidget = ({
  recaptchaSiteKey,
  ragpiGatewayUrl,
  ragpiSources,
  primaryColor,
  secondaryColor,
  logoUrl = "https://docs.ragpi.io/img/ragpi-logo-black.png",
  closedIconPosition = "bottom-right",
  enabled = true,
  registerControls,
}: Props) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isFetching, setIsFetching] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isWidgetVisible, setIsWidgetVisible] = useState(() => {
    const stored = localStorage.getItem("ragpi-widget-visible");
    return stored === null ? true : stored === "true";
  });
  const containerRef = useRef<HTMLDivElement | null>(null);
  // Mirror the open state in a ref so the imperative controls (registered once
  // on mount) can read the current value without being rebuilt every toggle.
  const isModalOpenRef = useRef(isModalOpen);
  useEffect(() => {
    isModalOpenRef.current = isModalOpen;
  }, [isModalOpen]);

  const handleOpenModal = () => {
    setIsModalOpen(true);
    // Lazily inject reCAPTCHA the first time the chat panel opens, so its token
    // is ready by send time without loading the script on every embedding page.
    // loadRecaptcha is idempotent, so reopening the panel is a no-op. Errors are
    // surfaced later at send time via executeRecaptcha.
    void loadRecaptcha(recaptchaSiteKey).catch(() => {});
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
  };

  const handleHideWidget = () => {
    setIsWidgetVisible(false);
    setIsModalOpen(false);
  };

  const handleShowWidget = () => {
    setIsWidgetVisible(true);
  };

  const handleClearHistory = () => {
    // Clear messages state
    setMessages([]);
    // Clear error state
    setError(null);
  };

  const handleSendMessage = async (message: string, recaptchaToken: string) => {
    // Guard before flipping isFetching, otherwise an empty submit returns early
    // and leaves the input locked with isFetching stuck true.
    if (message.trim() === "") return;

    setIsFetching(true);
    setError(null);
    setMessages([...messages, { role: "user", content: message }]);

    // Abort the request if the gateway never responds; without this a hung
    // request would keep isFetching true and lock the user out indefinitely.
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 60000);

    try {
      const request: ChatRequest = {
        sources: ragpiSources,
        messages: [...messages, { role: "user", content: message }],
      };

      const response = await fetch(`${ragpiGatewayUrl}/chat`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "x-recaptcha-token": recaptchaToken,
        },
        body: JSON.stringify(request),
        signal: controller.signal,
      });

      if (!response.ok) {
        let data;
        try {
          data = await response.json();
        } catch {
          // response body wasn't JSON
        }
        if (data?.error === "verification_failed") {
          setError(
            "We have detected unusual activity. Please try again later.",
          );

          document.dispatchEvent(
            new CustomEvent("ragpi:error", {
              detail: {
                message: "verification_failed",
              },
            }),
          );
        } else {
          console.error("Error:", data);
          setError("An error occurred. Please try again later.");

          document.dispatchEvent(
            new CustomEvent("ragpi:error", {
              detail: {
                message: JSON.stringify(data),
              },
            }),
          );
        }
      } else {
        const data: ChatResponse = await response.json();

        setMessages([
          ...request.messages,
          { role: "assistant", content: data.message },
        ]);
      }
    } catch (error) {
      const timedOut =
        error instanceof DOMException && error.name === "AbortError";
      console.error("Error:", error);
      setError(
        timedOut
          ? "The request timed out. Please try again."
          : "An error occurred. Please try again later.",
      );

      document.dispatchEvent(
        new CustomEvent("ragpi:error", {
          detail: {
            message: timedOut
              ? "timeout"
              : error instanceof Error
                ? error.message
                : String(error),
          },
        }),
      );
    } finally {
      // Always clear the timer and unlock the input, whatever the outcome.
      clearTimeout(timeoutId);
      setIsFetching(false);
    }
  };

  useEffect(() => {
    const handleEscapeKey = (e: globalThis.KeyboardEvent) => {
      if (e.key === "Escape") {
        handleCloseModal();
      }
    };

    if (isModalOpen) {
      document.addEventListener("keydown", handleEscapeKey);
    }

    return () => {
      document.removeEventListener("keydown", handleEscapeKey);
    };
  }, [isModalOpen]);

  useEffect(() => {
    // Persist widget visibility to localStorage
    localStorage.setItem("ragpi-widget-visible", String(isWidgetVisible));
  }, [isWidgetVisible]);

  useEffect(() => {
    // Publish the imperative controls so the embedding page can drive the panel
    // via window.ragpiWidget (see index.tsx). Built from stable setters + the
    // open-state ref, so it's registered once and never goes stale.
    if (!registerControls) return;
    const openPanel = () => {
      setIsWidgetVisible(true);
      setIsModalOpen(true);
      // Mirror handleOpenModal: warm up reCAPTCHA on first open. Idempotent.
      void loadRecaptcha(recaptchaSiteKey).catch(() => {});
    };
    registerControls({
      open: openPanel,
      close: () => setIsModalOpen(false),
      toggle: () => (isModalOpenRef.current ? setIsModalOpen(false) : openPanel()),
      isOpen: () => isModalOpenRef.current,
    });
    return () => registerControls(null);
  }, [recaptchaSiteKey, registerControls]);

  useEffect(() => {
    // Default Colors are set in the index.css file
    if (containerRef.current) {
      if (primaryColor) {
        containerRef.current.style.setProperty("--color-primary", primaryColor);
      } else {
        containerRef.current.style.removeProperty("--color-primary");
      }

      if (secondaryColor) {
        containerRef.current.style.setProperty(
          "--color-secondary",
          secondaryColor,
        );
      } else {
        containerRef.current.style.removeProperty("--color-secondary");
      }
    }
  }, [primaryColor, secondaryColor]);

  // If widget is disabled, render nothing
  if (!enabled) {
    return null;
  }

  return (
    <root.div ref={containerRef}>
      <style type="text/css">{styles}</style>

      {isWidgetVisible ? (
        <>
          <ChatButton onClick={handleOpenModal} onHide={handleHideWidget} />

          {isModalOpen && (
            <Suspense fallback={null}>
              <ChatModal
                logoUrl={logoUrl}
                recaptchaSiteKey={recaptchaSiteKey}
                onCloseModal={handleCloseModal}
                onClearHistory={handleClearHistory}
                onSendMessage={handleSendMessage}
                messages={messages}
                loading={isFetching}
                error={error}
              />
            </Suspense>
          )}
        </>
      ) : (
        <HubIconButton
          onClick={handleShowWidget}
          position={closedIconPosition}
        />
      )}
    </root.div>
  );
};
